/// Find user's global config at `~/.bivvy/config.toml` or `~/.bivvy/config.yml`.
fn find_user_global() -> Option<PathBuf> {
    let dir = dirs::home_dir()?.join(".bivvy");
    let toml_path = dir.join("config.toml");
    if toml_path.exists() {
        return Some(toml_path);
    }
    let yml_path = dir.join("config.yml");
    if yml_path.exists() {
        Some(yml_path)
    } else {
        None
