    fs::read_to_string(path).map_err(|e| {
        if e.kind() == std::io::ErrorKind::NotFound {
            BivvyError::ConfigNotFound {
                path: path.to_path_buf(),
            }
        } else {
            BivvyError::Io(e)
        }
    })
}

/// Load a single config file and parse it into BivvyConfig.
///
/// Automatically selects the TOML or YAML parser based on file extension.
///
/// # Errors
///
/// Returns `ConfigNotFound` if the file doesn't exist.
/// Returns `ConfigParseError` if the content is invalid.
pub fn load_config_file(path: &Path) -> Result<BivvyConfig> {
    let content = read_file(path)?;
    if is_toml_file(path) {
        parse_toml_config(&content, path)
    } else {
        parse_config(&content, path)
    }
}

/// Parse YAML content into BivvyConfig.
///
/// # Arguments
///
/// * `content` - The YAML content to parse
/// * `source_path` - Path for error reporting
pub fn parse_config(content: &str, source_path: &Path) -> Result<BivvyConfig> {
    serde_yaml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
        path: source_path.to_path_buf(),
        message: e.to_string(),
    })
}

/// Parse TOML content into BivvyConfig.
///
/// # Arguments
///
/// * `content` - The TOML content to parse
/// * `source_path` - Path for error reporting
pub fn parse_toml_config(content: &str, source_path: &Path) -> Result<BivvyConfig> {
    toml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
        path: source_path.to_path_buf(),
        message: e.to_string(),
    })
}

/// Convert a `toml::Value` into a `serde_yaml::Value`.
///
/// Used to feed TOML-sourced configs into the YAML-based merge pipeline.
fn toml_to_yaml_value(tv: toml::Value) -> serde_yaml::Value {
    match tv {
        toml::Value::String(s) => serde_yaml::Value::String(s),
        toml::Value::Integer(i) => serde_yaml::Value::Number(serde_yaml::Number::from(i)),
        toml::Value::Float(f) => {
            serde_yaml::Value::Number(serde_yaml::Number::from(f))
        }
        toml::Value::Boolean(b) => serde_yaml::Value::Bool(b),
        toml::Value::Datetime(dt) => serde_yaml::Value::String(dt.to_string()),
        toml::Value::Array(arr) => {
            let seq = arr.into_iter().map(toml_to_yaml_value).collect();
            serde_yaml::Value::Sequence(seq)
        }
        toml::Value::Table(table) => {
            let map = table
                .into_iter()
                .map(|(k, v)| (serde_yaml::Value::String(k), toml_to_yaml_value(v)))
                .collect();
            serde_yaml::Value::Mapping(map)
        }
    }
}

/// Load a config file as raw YAML Value (for merging).
///
/// Returns a `serde_yaml::Value` without deserializing into
/// `BivvyConfig`, which allows for deep merging before final parsing.
/// Handles both YAML and TOML files based on extension.
pub fn load_config_value(path: &Path) -> Result<serde_yaml::Value> {
    let content = read_file(path)?;

    if is_toml_file(path) {
        let tv: toml::Value =
            toml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
                path: path.to_path_buf(),
                message: e.to_string(),
            })?;
        Ok(toml_to_yaml_value(tv))
    } else {
        serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
            path: path.to_path_buf(),
            message: e.to_string(),
        })
    }
}

